window.DOSIK=window.DOSIK||{};DOSIK["yc_youthunderstand"]={"1":[{"t":"tree","title":"청소년기의 특성","root":"청소년기","branches":[["과도기","아동에서 성인으로 이행하는 과도기적인 단계이다"],["사고","추상적 사고가 가능해지는 시기이다"],["또래","또래집단의 영향이 중요해지는 시기이다"],["사춘기","청소년기는 사춘기의 시작과 함께 시작한다 · 사춘기에는 2차 성징이 나타나면서 성적 호기심이 증가한다"],["연장","오늘날 청소년기는 더 연장되는 추세이다 · 최근 사회변화에 따라 청소년기가 연장되는 추세에 있다"],["연령","청소년과 관련된 연령은 법령에 따라 다르다"]]}],"2":[{"t":"table","title":"생태체계","head":["체계","의미"],"rows":[["미시체계","청소년이 직접 상호작용하는 환경을 포함한다"],["중간체계","미시체계들 간의 관계성을 의미한다"],["외체계","정부기관은 외체계에 해당된다"],["시간체계","전 생애에 걸쳐 일어나는 변화와 사회ㆍ역사적인 환경을 의미한다"]]}],"3":[{"t":"cause","title":"급격한 신체변화","causes":["청소년기는 신체적 성장급등이 이루어지는 시기이다","급격한 신체변화로 인해 자신의 체형에 대한 불만족을 느끼는 경우"],"result":"청소년의 정신건강에 부정적인 영향을 미칠 수 있다"},{"t":"def","term":"신체적 조숙","text":"또래에 비해 신체적 발달이 빨리 이루어지는 경우"},{"t":"def","term":"이차 성징","text":"뚜렷해지는 것과 관련 깊은 내분비선","ex":["뇌하수체","생식선"]}],"4":[{"t":"cause","title":"자기중심적 사고","causes":["다른 사람들의 눈에 띄고 싶은 욕망으로부터 나온다"],"result":"청소년기 자기중심적 사고","effects":["타인들이 자신을 주시하고 있다고 생각한다","스스로 주인공이 되어 무대 위에 있는 것처럼 행동한다"]}],"7":[{"t":"table","title":"도덕성 발달 이론","head":["학자","이론"],"rows":[["콜버그(L. Kohlberg)","도덕성 발달 이론에 따르면 4단계는 법과 질서 지향의 단계이다"],["길리건(C. Gilligan)","배려 지향적 도덕성 이론을 제시하였다"],["반두라(A. Bandura)","도덕적 행동 발달을 사회학습이론으로 설명하였다"],["프로이트(S. Freud)","도덕성 발달이 초자아의 발현을 통해서 이루어진다고 보았다"]]}],"8":[{"t":"tree","title":"청소년기 사회성","root":"사회성 발달","branches":[["가족","부모와 가족으로부터 자율성을 추구한다"],["또래관계","자아정체감 형성의 기회를 제공한다"],["아동기보다","친구들과 많은 시간을 보낸다 · 또래집단에 대한 동조성이 높게 나타난다"]]}],"15":[{"t":"tree","title":"학업 문제","root":"청소년 학업 문제","branches":[["학업스트레스","높게 나타나는 경향이 있다"],["시험불안","과도하면 청소년의 학업수행에 부정적인 영향을 미친다"],["학습장애","읽기, 쓰기, 셈하기 등의 기초학습영역에서 문제를 보이는 경우를 말한다"],["학업 성취가 낮은 청소년","그 원인을 내부 요인보다 외부 요인으로 돌리는 경향이 있다"]]}],"16":[{"t":"table","title":"학교폭력 용어","head":["용어","뜻"],"rows":[["피해학생","학교폭력으로 인하여 피해를 입은 학생을 말한다"],["장애학생","신체적ㆍ정신적ㆍ지적 장애 등으로 「장애인 등에 대한 특수교육법」 제15조에서 규정하는 특수교육이 필요한 학생을 말한다"],["가해학생","가해자 중에서 학교폭력을 행사하거나 그 행위에 가담한 학생을 말한다"],["사이버 따돌림","인터넷, 휴대전화 등 정보통신기기를 이용하여 학생들이 특정 학생들을 대상으로 지속적, 반복적으로 심리적 공격을 가하거나, 특정 학생과 관련된 개인정보 또는 허위사실을 유포하여 상대방이 고통을 느끼도록 하는 모든 행위를 말한다"]]}],"18":[{"t":"tree","title":"청소년복지 지원법","root":"청소년복지 지원법","branches":[["목적","관할구역의 위기청소년을 조기에 발견하여 보호하고, 청소년복지 및 청소년보호를 효율적으로 수행함을 목적으로 한다"],["생활관","주거 연계, 생활관 운영, 자립 지원 서비스를 지원한다"],["청소년증 발급","9세 이상 18세 이하의 청소년에게 발급한다 · 여성가족부가 청소년증의 발급에 필요한 사항을 정한다 · 특별자치시장ㆍ특별자치도지사 또는 시장ㆍ군수ㆍ구청장이 발급할 수 있다"],["청소년증 양도","다른 사람에게 양도하거나 빌려주어서는 아니된다"],["통합지원체계","국가는 구축ㆍ운영을 지원하여야 한다 · 광역시는 전담기구를 설치할 수 있다 · 교육청은 필수연계기관이다"]]},{"t":"flow","title":"생활관 거주","steps":["생활관 입소는 사례심의위원회에서 결정한다","최초 3개월 이내에 거주할 수 있다","필요시 추가 3개월 1회 연장 가능하다"]}]};
